import{_ as r,o,c as i,ag as s,j as t,a as n,t as a}from"./chunks/framework.DB9Ll7VW.js";const y=JSON.parse('{"title":"Email & notifications","description":"Edit the transactional emails Sikshya sends, configure deliverability, and unlock branded templates, drip notifications, ESP delivery, and CRM automation with Sikshya Pro.","frontmatter":{"title":"Email & notifications","description":"Edit the transactional emails Sikshya sends, configure deliverability, and unlock branded templates, drip notifications, ESP delivery, and CRM automation with Sikshya Pro."},"headers":[],"relativePath":"email-settings.md","filePath":"email-settings.md","lastUpdated":1778327862000}'),d={name:"email-settings.md"},u={tabindex:"0"};function p(l,e,m,c,g,h){return o(),i("div",null,[e[32]||(e[32]=s('<h1 id="email-notifications" tabindex="-1">Email &amp; notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email &amp; notifications&quot;">​</a></h1><div class="doc-pro-callout"><span class="doc-pro-pill">Pro</span><span><strong>Branded templates, drip notifications, ESP delivery &amp; CRM automation are Sikshya Pro.</strong> The free plugin sends every transactional email out of the box.</span><a class="doc-pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing" target="_blank" rel="noopener">View pricing →</a></div><p>Sikshya sends transactional emails at every important moment — welcome, enrollment, purchase, completion, certificate issued. This page is the practical guide for editing them, making them deliverable, and unlocking branded / automated email with Pro.</p><h2 id="the-email-hub" tabindex="-1">The Email hub <a class="header-anchor" href="#the-email-hub" aria-label="Permalink to &quot;The Email hub&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Email</span>. Two tabs:</p><ul><li><strong>Delivery</strong> — site-wide sender settings.</li><li><strong>Templates</strong> — every transactional email, listed individually.</li></ul><h2 id="delivery-settings" tabindex="-1">Delivery settings <a class="header-anchor" href="#delivery-settings" aria-label="Permalink to &quot;Delivery settings&quot;">​</a></h2><p>The Delivery tab covers the <strong>basics that decide whether your emails land in inboxes or spam</strong>:</p><ul><li><strong>Main LMS contact email</strong> — the academy&#39;s contact address (used in receipts, &quot;reply to&quot; headers).</li><li><strong>Where to send admin notices</strong> — admin notifications go here. Default: site admin email.</li><li><strong>From address</strong> — the visible &quot;From&quot; address. Use a <code>noreply@yourdomain.com</code> on a domain you control.</li><li><strong>From name</strong> — usually your academy / company name.</li><li><strong>Reply address</strong> — where replies go (default: same as From).</li><li><strong>Allow Sikshya to send transactional email</strong> — master kill-switch. Leave on.</li><li><strong>Email the certificate to the learner</strong> — toggle to also attach / link the certificate in the Course completed email.</li></ul><div class="ui-tip"><strong>Important:</strong> WordPress&#39;s built-in <code>wp_mail()</code> is unreliable on most hosts. Connect a real ESP (SendGrid, Postmark, Mailgun, Amazon SES) using a transport plugin like <strong>WP Mail SMTP</strong>, <strong>FluentSMTP</strong>, or <strong>Post SMTP</strong>. Then configure SPF, DKIM, and DMARC for the From domain.</div><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>The Templates tab lists every email type in your store, with columns:</p><ul><li><strong>Name</strong> — what the template does.</li><li><strong>Audience</strong> — admin, instructor, or learner.</li><li><strong>Trigger</strong> — what fires it (event name).</li><li><strong>Status</strong> — Active or Inactive.</li></ul><p>Search the list by name. Tick rows to <strong>Enable selected</strong>, <strong>Disable selected</strong>, or bulk-delete custom templates.</p><h3 id="free-transactional-emails" tabindex="-1">Free transactional emails <a class="header-anchor" href="#free-transactional-emails" aria-label="Permalink to &quot;Free transactional emails&quot;">​</a></h3><p>These ship with the free plugin and are seeded on activation:</p><table tabindex="0"><thead><tr><th>Template</th><th>Audience</th><th>Triggered by</th></tr></thead><tbody><tr><td><strong>Welcome email</strong></td><td>Learner</td><td>New user registration</td></tr><tr><td><strong>Course enrollment</strong></td><td>Learner</td><td>Enrolled in a course</td></tr><tr><td><strong>New enrollment notice</strong></td><td>Admin</td><td>Enrolled in a course</td></tr><tr><td><strong>Instructor&#39;s new enrollment</strong></td><td>Instructor</td><td>Enrolled in a course</td></tr><tr><td><strong>Payment receipt</strong></td><td>Learner</td><td>Order fulfilled</td></tr><tr><td><strong>Order fulfilled notice</strong></td><td>Admin</td><td>Order fulfilled</td></tr><tr><td><strong>Course completed</strong></td><td>Learner</td><td>Course completion</td></tr><tr><td><strong>Certificate issued</strong></td><td>Learner</td><td>Certificate issued</td></tr><tr><td><strong>Progress reminder</strong></td><td>Learner</td><td>Inactivity reminder (Pro extends)</td></tr></tbody></table><h3 id="pro-only-templates" tabindex="-1">Pro-only templates <a class="header-anchor" href="#pro-only-templates" aria-label="Permalink to &quot;Pro-only templates&quot;">​</a></h3><p>When a Pro add-on is active, more templates appear here. Examples:</p><table tabindex="0"><thead><tr><th>Template</th><th>Available with</th></tr></thead><tbody><tr><td><strong>Drip lesson unlocked</strong> <span class="pro-pill">PRO</span></td><td>Drip notifications add-on</td></tr><tr><td><strong>Drip course unlocked</strong> <span class="pro-pill">PRO</span></td><td>Drip notifications add-on</td></tr><tr><td><strong>Daily drip digest</strong> <span class="pro-pill">PRO</span></td><td>Drip notifications add-on</td></tr><tr><td><strong>New question</strong> (instructor) <span class="pro-pill">PRO</span></td><td>Community discussions / Q&amp;A</td></tr></tbody></table><h2 id="edit-a-template" tabindex="-1">Edit a template <a class="header-anchor" href="#edit-a-template" aria-label="Permalink to &quot;Edit a template&quot;">​</a></h2><p>Click any template name to open the editor:</p><h3 id="top-of-the-page" tabindex="-1">Top of the page <a class="header-anchor" href="#top-of-the-page" aria-label="Permalink to &quot;Top of the page&quot;">​</a></h3><ul><li><strong>← Back to templates</strong> — list view.</li><li><strong>Preview</strong> — opens a sample render in a new tab.</li><li><strong>Save template</strong> — persists changes.</li><li><strong>Status toggle</strong> — Active / Inactive.</li></ul><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3>',25)),t("ul",null,[e[6]||(e[6]=t("li",null,[t("strong",null,"Template name"),n(" — internal label (won't change behavior).")],-1)),e[7]||(e[7]=t("li",null,[t("strong",null,"Description"),n(" — short note for your team.")],-1)),e[8]||(e[8]=t("li",null,[t("strong",null,"Trigger event"),n(" — system templates show this as read-only; custom templates let you pick from the trigger list.")],-1)),t("li",null,[e[0]||(e[0]=t("strong",null,"Send to (merge tags)",-1)),e[1]||(e[1]=n(" — who receives this. Use tags like ",-1)),t("code",null,a(l.learner_email),1),e[2]||(e[2]=n(", ",-1)),t("code",null,a(l.instructor_email),1),e[3]||(e[3]=n(", ",-1)),t("code",null,a(l.admin_email),1),e[4]||(e[4]=n(".",-1))]),t("li",null,[e[5]||(e[5]=t("strong",null,"Subject line",-1)),n(' — supports merge tags (e.g. "Welcome to '+a(l.site_name)+'!").',1)]),e[9]||(e[9]=t("li",null,[t("strong",null,"Email body (HTML)"),n(" — the full message. The right rail lists every variable you can use; click one to copy.")],-1))]),e[33]||(e[33]=t("h3",{id:"available-merge-tags",tabindex:"-1"},[n("Available merge tags "),t("a",{class:"header-anchor",href:"#available-merge-tags","aria-label":'Permalink to "Available merge tags"'},"​")],-1)),e[34]||(e[34]=t("p",null,"The most-used:",-1)),t("table",u,[e[28]||(e[28]=t("thead",null,[t("tr",null,[t("th",null,"Tag"),t("th",null,"Renders")])],-1)),t("tbody",null,[t("tr",null,[t("td",null,[t("code",null,a(l.site_name),1)]),e[10]||(e[10]=t("td",null,"Your site / academy name",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.site_url),1)]),e[11]||(e[11]=t("td",null,"Site root URL",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.learner_name),1)]),e[12]||(e[12]=t("td",null,"Learner's display name",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.learner_first_name),1)]),e[13]||(e[13]=t("td",null,"First name (parsed)",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.learner_email),1)]),e[14]||(e[14]=t("td",null,"Learner's email",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.course_title),1)]),e[15]||(e[15]=t("td",null,"Course title",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.course_url),1)]),e[16]||(e[16]=t("td",null,"Permalink to the course",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.lesson_title),1)]),e[17]||(e[17]=t("td",null,"Lesson title (where applicable)",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.quiz_title),1)]),e[18]||(e[18]=t("td",null,"Quiz title",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.order_id),1)]),e[19]||(e[19]=t("td",null,"Sikshya order id",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.order_total),1)]),e[20]||(e[20]=t("td",null,"Total in display currency",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.order_url),1)]),e[21]||(e[21]=t("td",null,"Order detail URL",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.certificate_url),1)]),e[22]||(e[22]=t("td",null,"Issued certificate URL",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.instructor_name),1)]),e[23]||(e[23]=t("td",null,"Instructor display name",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.login_url),1)]),e[24]||(e[24]=t("td",null,"Login URL",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.account_url),1)]),e[25]||(e[25]=t("td",null,"Learner account URL",-1))]),t("tr",null,[t("td",null,[t("code",null,a(l.date),1),e[26]||(e[26]=n(" / ",-1)),t("code",null,a(l.time),1)]),e[27]||(e[27]=t("td",null,"Now (site timezone)",-1))])])]),t("p",null,[e[29]||(e[29]=n("Whitespace inside braces is OK — ",-1)),t("code",null,a(l.course_title),1),e[30]||(e[30]=n(" works the same as ",-1)),t("code",null,a(l.course_title),1),e[31]||(e[31]=n(".",-1))]),e[35]||(e[35]=s('<h3 id="locked-templates" tabindex="-1">Locked templates <a class="header-anchor" href="#locked-templates" aria-label="Permalink to &quot;Locked templates&quot;">​</a></h3><p>Some rows show a lock icon and &quot;Add-on required&quot; text. These templates only render when the corresponding Pro add-on is on.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Drip notifications</span></div><p class="pro-callout__desc">When you use the <strong>Content drip</strong> add-on, the <strong>Drip notifications</strong> add-on emails learners when their next lesson unlocks. Three templates: lesson unlocked, course unlocked, daily digest. Combine them with drip rules for a paced cohort experience.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock drip notifications →</a></div><h2 id="test-a-template" tabindex="-1">Test a template <a class="header-anchor" href="#test-a-template" aria-label="Permalink to &quot;Test a template&quot;">​</a></h2><p>The fastest test: enroll yourself in a course in a private window and watch the <strong>Welcome</strong> + <strong>Enrollment</strong> + <strong>Receipt</strong> emails land. Or:</p><ul><li>Click the <strong>Preview</strong> button on the template editor — opens a rendered preview without sending.</li><li>Send yourself a manual test enrollment from <span class="screen-path">People → Enrollments</span> → manual enroll.</li></ul><p>If a template doesn&#39;t fire:</p><ul><li>Check the template <strong>Status</strong> is Active.</li><li>Check delivery is on (<span class="screen-path">Email → Delivery → Allow Sikshya to send transactional email</span>).</li><li>Check your SMTP / ESP plugin shows the message in its log.</li></ul><h2 id="pro-email-features" tabindex="-1">Pro email features <a class="header-anchor" href="#pro-email-features" aria-label="Permalink to &quot;Pro email features&quot;">​</a></h2><p>Sikshya Pro layers four email-related add-ons on top of the free transactional pipeline:</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Professional email delivery &amp; branded templates</span></div><p class="pro-callout__desc">Plug Sikshya into a real transactional ESP with a guided UI (no third-party plugin needed) and wrap every message in a branded multi-template kit (header, footer, accent color, logo).</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock branded delivery →</a></div><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Email advanced customization</span></div><p class="pro-callout__desc">Per-template HTML overrides, extra layout slots, conditional content blocks (different copy for different course categories).</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced customization →</a></div><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">CRM email automation</span></div><p class="pro-callout__desc">Trigger sequences (Day 0 → Day 3 → Day 7 → Day 14) on enrollment, completion, abandoned cart. Each step is a template; the engine handles timing and branching.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock CRM sequences →</a></div><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Email marketing (Mailchimp / MailerLite)</span></div><p class="pro-callout__desc">Sync enrollments and completions to a Mailchimp or MailerLite list / segment automatically. Run drip campaigns and broadcasts in your marketing tool, fed by Sikshya activity.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock marketing sync →</a></div><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>If you&#39;ve enabled email logging (in <span class="screen-path">Tools</span>), every email send is recorded with timestamp, recipient, template, and status. Open <span class="screen-path">Tools → Activity log</span> <span class="pro-pill">PRO</span> for the full audit trail.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/docs/third-party-integrations">Pro add-ons</a> — every Pro feature listed.</li><li><a href="/docs/troubleshooting">Troubleshooting</a> — fix bounced or missing email.</li><li><a href="/docs/hooks-filters">Hooks &amp; filters</a> — extend email behavior in code.</li></ul>',18))])}const b=r(d,[["render",p]]);export{y as __pageData,b as default};
